SELECT jsonb_build_object('observedAt',now(),'rows',(SELECT jsonb_agg(to_jsonb(t) ORDER BY source_game_id,team_id) FROM public.roster_optimizer_team_games t WHERE game_key='477' AND source_game_id BETWEEN 2026020084 AND 2026020140),'audits',(SELECT jsonb_agg(to_jsonb(a)) FROM (SELECT job_name,run_time,status,rows_affected,details FROM public.cron_job_audit WHERE job_name='update-roster-optimizer-schedule' AND run_time>='2026-10-14T00:05:00Z' ORDER BY run_time DESC LIMIT 3) a)) AS verification;
